{
"predictors": [
{
"name": "Social Media Sentiment",
"construction": "Measure the sentiment of social media posts about a company over the past month, using natural language processing algorithms.",
"rationale": "The sentiment of social media posts can reflect the public’s view on a company, which can influence its stock price.",
"higher_returns_for": "Companies with positive social media sentiment"
},
{
"name": "Green Investment Ratio",
"construction": "Calculate the ratio of a company’s investments in green/eco-friendly technologies to its total investments over the past year.",
"rationale": "Companies that invest in green technologies are likely to benefit from increasing environmental regulations and public demand for sustainable products.",
"higher_returns_for": "Companies with a higher green investment ratio"
},
{
"name": "Employee Satisfaction Index",
"construction": "Use employee reviews from online platforms to create an index of employee satisfaction.",
"rationale": "Happy employees can lead to higher productivity and better company performance.",
"higher_returns_for": "Companies with a high employee satisfaction index"
},
{
"name": "Cybersecurity Breach Probability",
"construction": "Use historical data on cybersecurity breaches and a company’s current cybersecurity measures to estimate the probability of a future breach.",
"rationale": "Cybersecurity breaches can cause significant financial and reputational damage to a company.",
"higher_returns_for": "Companies with a low probability of a cybersecurity breach"
},
{
"name": "Customer Loyalty Score",
"construction": "Use customer survey data to calculate a score representing customer loyalty.",
"rationale": "Companies with loyal customers are likely to have more stable and predictable revenue streams.",
"higher_returns_for": "Companies with a high customer loyalty score"
},
{
"name": "R&D Efficiency",
"construction": "Calculate the R&D expenditure as a percentage of new product revenue over the last year.",
"rationale": "High R&D efficiency can indicate a company’s ability to bring profitable new products to market.",
"higher_returns_for": "Companies with a lower R&D expenditure to new product revenue ratio"
},
{
"name": "Corporate Governance Score",
"construction": "Use data from corporate governance reports to create a score representing the quality of a company’s governance.",
"rationale": "Good corporate governance can help protect shareholder interests and improve company performance.",
"higher_returns_for": "Companies with a high corporate governance score"
},
{
"name": "Managerial Compensation Structure",
"construction": "Calculate the ratio of a CEO’s performance-based compensation (like stock options) to their total compensation.",
"rationale": "A higher ratio could align the CEO’s interests more closely with shareholders and incentivize better company performance.",
"higher_returns_for": "Companies where a larger portion of CEO compensation is performance-based"
},
{
"name": "Product Recalls Ratio",
"construction": "Calculate the ratio of the number of product recalls over the past year to the total number of products sold.",
"rationale": "A high ratio can indicate quality control issues that could harm a company’s reputation and financial performance.",
"higher_returns_for": "Companies with a lower product recalls ratio"
},
{
"name": "Tax Optimization Index",
"construction": "Use data on a company’s tax payments and tax planning strategies to create an index representing its tax optimization level.",
"rationale": "Effective tax optimization can increase a company’s net profit and therefore its stock return.",
"higher_returns_for": "Companies with a high tax optimization index"
}
]
}
